statement:
You are given an integer array `nums` and an integer `threshold`. A contiguous, non-empty block `nums[l..r]` qualifies when all three rules hold:

- its first value `nums[l]` is even;
- every two neighbouring values inside it have different parity, so the block reads even, odd, even, odd, ...;
- no value inside it is greater than `threshold`.

Return the length of the longest qualifying block, or `0` if no block qualifies.

validator:
function validate([nums, threshold]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each value in nums is an integer from 1 to 100.';
  if (!Number.isInteger(threshold) || threshold < 1 || threshold > 100) return 'threshold is an integer from 1 to 100.';
  return null;
}

reference:
function longestAlternatingSubarray(nums, threshold) {
  let best = 0;
  let left = 0;
  while (left < nums.length) {
    if (nums[left] % 2 !== 0 || nums[left] > threshold) {
      left++;
      continue;
    }
    let right = left;
    while (right + 1 < nums.length && nums[right + 1] <= threshold && nums[right + 1] % 2 !== nums[right] % 2) {
      right++;
    }
    best = Math.max(best, right - left + 1);
    left = right + 1;
  }
  return best;
}

brute:
function longestAlternatingSubarray(nums, threshold) {
  let best = 0;
  for (let l = 0; l < nums.length; l++) {
    for (let r = l; r < nums.length; r++) {
      const part = nums.slice(l, r + 1);
      const ok = part[0] % 2 === 0
        && part.every(v => v <= threshold)
        && part.every((v, i) => i === 0 || v % 2 !== part[i - 1] % 2);
      if (ok) best = Math.max(best, part.length);
    }
  }
  return best;
}

