function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const top = size === 'large' ? 100 : 10;
  const threshold = 1 + Math.floor(rand() * top);
  const nums = [];
  for (let i = 0; i < n; i++) {
    let value = 1 + Math.floor(rand() * top);
    // Often keep the parity alternating so long qualifying blocks appear.
    if (i > 0 && rand() < 0.7 && value % 2 === nums[i - 1] % 2) value = value === top ? value - 1 : value + 1;
    nums.push(value);
  }
  return [nums, threshold];
}
